from common import *
import ast
if __name__=='__main__':
 save_source(__file__)
 p=TMP/'publish.py';s=p.read_text()
 marker=" if len(summary['style_pairs'])==3:"
 insert=""" summary['paired_seed_style']={}
 summary['paired_year_changes']={}
 for h in [7,15,20]:
  a,b=f'h{h}q10',f'h{h}continuous'
  if a not in docs or b not in docs:continue
  summary['paired_seed_style'][str(h)]={}
  for regime in ['D','F','T']:
   summary['paired_seed_style'][str(h)][regime]={}
   for key in ['net_ann','net_sharpe']:
    differences={str(seed):docs[a]['pools']['all']['seeds'][str(seed)]['head_regimes'][regime]['3']['5'][key]-docs[b]['pools']['all']['seeds'][str(seed)]['head_regimes'][regime]['3']['5'][key] for seed in SEEDS}
    summary['paired_seed_style'][str(h)][regime][key]={'differences':differences,'positive':sum(v>1e-12 for v in differences.values()),'negative':sum(v<-1e-12 for v in differences.values())}
  summary['paired_year_changes'][str(h)]={year:{key:official(docs[a])['head_years'][year]['3']['5'][key]-official(docs[b])['head_years'][year]['3']['5'][key] for key in ['net_ann','net_sharpe']} for year in [str(y) for y in range(2020,2027)]}
"""
 assert marker in s;s=s.replace(marker,insert+marker)
 marker=" if 'universality' in summary:"
 insert=""" if summary['paired_seed_style']:
  table('逐种子同向性 · 10档相对连续',['H','风格','收益改善种子/5','收益下降种子/5','夏普改善种子/5','夏普下降种子/5'],[[h,r,str(v['net_ann']['positive']),str(v['net_ann']['negative']),str(v['net_sharpe']['positive']),str(v['net_sharpe']['negative'])] for h,styles in summary['paired_seed_style'].items() for r,v in styles.items()])
"""
 assert marker in s;s=s.replace(marker,insert+marker)
 ast.parse(s);p.write_text(s)
 print('Added paired per-seed style win counts and per-year differences.')
